-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 26: Bancos de dados relacional/objeto — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('82c71ce3-42d2-56f8-9925-8ea66c4a5de4', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Na aproximação defendida por Date, recursos de objetos devem ser integrados sobre:', '["Tabelas sem restrições.","Ausência de tipos definidos pelo usuário.","Um arquivo exclusivo por aplicação.","Navegação física obrigatória.","Uma base conceitual relacional coerente."]'::jsonb, 4, 'O autor sustenta a manutenção dos princípios relacionais na integração.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.1, páginas 1357–1360 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a145b459-1490-5f29-aaab-2f032fc42df8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Qual recurso é central para a visão relacional/objeto defendida pelo autor?', '["Remoção de visões.","Exclusão de chaves candidatas.","Tipos definidos pelo usuário com operadores apropriados.","Ponteiros obrigatórios visíveis ao usuário.","Uma tabela por método."]'::jsonb, 2, 'Suporte adequado a domínios permite lidar com valores de maior complexidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.1, páginas 1357–1360 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f27b585-b5e5-5135-8492-158e10486435', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Qual equivalência é identificada como o primeiro grande erro?', '["Valor = valor.","Relação = valor relacional.","Classe de objetos = tipo, na interpretação de domínio.","Classe de objetos = relvar.","Operador de leitura = operação sem atualização."]'::jsonb, 3, 'O autor critica confundir o conceito de tipo com uma variável de relação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d305277f-3b90-5500-957c-dd90cc122b33', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Na equivalência preferida pelo autor, a classe de objetos aproxima-se de:', '["Um índice físico.","Um domínio ou tipo.","Um arquivo de log.","Uma relvar obrigatoriamente.","Uma transação."]'::jsonb, 1, 'Essa leitura separa a definição de valores das coleções armazenadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f2c87215-fd96-56cd-9aad-717e30e2d28b', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Por que uma relvar não deve ser tratada simplesmente como um tipo?', '["Porque tipos são sempre arquivos.","Porque relvars não admitem restrições.","Porque relvars não possuem valores.","Porque tipos nunca possuem operadores.","Ela é uma variável que assume valores relacionais, não o conjunto de valores admissíveis de um domínio."]'::jsonb, 4, 'A distinção tipo/variável é essencial à crítica do capítulo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('287606eb-812a-58f1-9ff1-e177ab3ed63d', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Difícil', 'Uma projeção gera uma nova relação. Isso exige definir automaticamente uma nova classe com métodos próprios?', '["Sim, toda consulta exige uma nova classe persistente.","Sim, antes de qualquer leitura.","Não; o resultado possui tipo relacional inferível sem essa equivalência artificial.","Não, porque projeções não produzem relações.","Sim, apenas quando há uma coluna."]'::jsonb, 2, 'O fechamento relacional deve continuar natural para resultados derivados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2f6e79f4-fa71-597b-b3a9-1a8577d8833a', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma tabela armazena valores de vários atributos tipados. Seus tipos devem ser confundidos com a própria tabela?', '["Não; os domínios dos atributos e a relvar exercem papéis distintos.","Sim, pois tipo e variável são sinônimos.","Sim, apenas em sistemas com métodos.","Não, porque tabelas não possuem atributos.","Sim, toda coluna é uma cópia da tabela."]'::jsonb, 0, 'Uma tabela pode usar tipos definidos pelo usuário sem se tornar equivalente a um desses tipos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dbf68a9e-9555-5356-a35e-4d9ea5465b08', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'O segundo grande erro, na terminologia de Date, consiste em:', '["Manter índices internamente.","Misturar ponteiros e relações no nível do modelo.","Usar valores numéricos em atributos.","Permitir expressões relacionais aninhadas.","Definir tipos próprios."]'::jsonb, 1, 'A crítica é à exposição conceitual de ponteiros, não a toda técnica física de implementação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2f3eeae4-3445-51d2-9a71-646a1847abd2', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Um SGBD usa ponteiros internamente em um índice. Isso, sozinho, comete o segundo grande erro?', '["Sim, qualquer implementação com ponteiros deixa de ser relacional.","Não, porque índices não podem conter referências.","Sim, se o índice for usado em consulta.","Não; a crítica se refere aos ponteiros expostos no modelo de dados.","Sim, mesmo sem exposição ao usuário."]'::jsonb, 3, 'Modelo lógico e organização física precisam ser distinguidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d93f58eb-e634-502a-902d-aadb7272b354', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Difícil', 'O princípio da informação estabelece, em termos relacionais, que a informação seja representada por:', '["Valores em relações.","Somente nomes de arquivos.","Endereços físicos manipulados pelas aplicações.","Métodos sem valores.","Ponteiros externos obrigatórios."]'::jsonb, 0, 'A crítica à mistura de ponteiros considera a uniformidade da representação informacional.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f2ec4d1-923f-5503-b2f4-1fccc41f2572', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Por que exigir navegação por referências pode enfraquecer a uniformidade relacional?', '["Porque garante fechamento automaticamente.","Cria formas de acesso distintas das operações sobre valores em relações.","Porque elimina todos os tipos escalares.","Porque toda referência é uma chave primária.","Porque impede qualquer armazenamento."]'::jsonb, 1, 'O capítulo questiona a introdução de um segundo mecanismo conceitual de associação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9f135694-68c8-58bd-8f53-36b6dc196a14', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Substituir uma relvar básica por uma visão equivalente deve preservar, idealmente:', '["A possibilidade de uso compatível pelas aplicações.","Os endereços físicos de cada tupla.","A localização de todas as cópias.","A ordem de todas as páginas.","A identidade dos arquivos do sistema operacional."]'::jsonb, 0, 'O princípio da permutabilidade busca evitar dependências artificiais do caráter básico ou derivado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1107c6c8-9cab-58ee-b644-2be03898437e', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Um pacote de tipos geoespaciais acrescenta principalmente:', '["Apenas cópias físicas das tabelas.","Somente temas visuais.","Somente logs de auditoria.","Tipos e operadores específicos de um domínio de aplicação.","Exclusivamente usuários."]'::jsonb, 3, 'Extensibilidade de tipos permite incorporar novas categorias de valores e operações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fb3f6698-af58-5055-96a9-ca6cbe725c97', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Adicionar novos tipos pode exigir integração com quais componentes?', '["Exclusivamente a tabela de usuários.","Somente o editor de texto.","Compilador, otimizador e gerenciador de armazenamento.","Apenas a tela de login.","Somente o serviço de impressão."]'::jsonb, 2, 'O suporte adequado não se limita a reconhecer um nome de tipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dabfb682-e4d9-5789-9984-61e7183ee0ae', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Por que o otimizador pode precisar conhecer operadores de um novo pacote de tipos?', '["Para estimar custos e escolher formas adequadas de execução.","Para remover a tipagem.","Para alterar os valores retornados arbitrariamente.","Para decidir o significado de todas as regras de negócio.","Para desativar transações."]'::jsonb, 0, 'Operadores especializados podem possuir custos e possibilidades de acesso específicos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf6894b0-a23c-52bd-bd0e-eeee8dfb92e8', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Armazenar um conteúdo complexo como bloco opaco garante boa consulta a suas propriedades?', '["Sim, qualquer bloco expõe todos os seus campos.","Sim, pela mera presença de uma chave.","Não, porque tipos complexos não podem existir.","Sim, desde que tenha muitos bytes.","Não; operações e suporte de consulta precisam estar disponíveis."]'::jsonb, 4, 'Armazenar bytes e oferecer operações úteis sobre seus valores são capacidades diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d318df0a-1733-56d2-b6db-650af4d8fdf3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual combinação expressa a aproximação considerada útil no capítulo?', '["Somente navegação física e ausência de predicados.","Relvars sem tipos.","Ponteiros sem restrições.","Métodos sem persistência nem consultas.","Valores complexos bem tipados e consultas relacionais sobre coleções."]'::jsonb, 4, 'Tipos e relações atendem a necessidades complementares.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.5, páginas 1382–1384 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3afc2578-d118-5347-b90d-142c09a3bf54', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Segundo os recursos SQL descritos, tipos definidos pelo usuário podem servir para:', '["Eliminar a definição de esquemas.","Criar senhas automáticas.","Definir tipos de colunas em tabelas.","Substituir obrigatoriamente todos os SELECTs.","Impedir qualquer restrição."]'::jsonb, 2, 'O capítulo menciona tipos DISTINCT e estruturados no suporte SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.6, páginas 1385–1393 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c5b5545c-cfe2-503e-930b-facb449a4ec0', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Qual par de categorias de tipos definidos pelo usuário é discutido no suporte SQL?', '["Logs físicos e lógicos.","Tipos DISTINCT e tipos estruturados.","Bloqueios compartilhados e exclusivos.","Transações locais e globais.","Índices primários e secundários."]'::jsonb, 1, 'As categorias de tipos são diferentes dos mecanismos de índice ou transação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.6, páginas 1385–1393 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3568ba74-ad0a-5856-a6bb-750df01f5dee', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'O rótulo comercial relacional/objeto garante, segundo a crítica de Date, fidelidade conceitual ao modelo defendido?', '["Sim, se houver interface gráfica.","Sim, se o banco tiver muitas tabelas.","Não, porque tipos próprios são proibidos no modelo.","Não; é necessário examinar os recursos e sua semântica.","Sim, o nome é uma prova suficiente."]'::jsonb, 3, 'O autor distingue propostas conceituais e implementações comercializadas sob o mesmo rótulo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.1, páginas 1357–1360 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
